/** Encrypted browser vault. Non-extractable key in IndexedDB, not an account login. */
let dbp,epoch=0,revision=0;
function db(){return dbp??=new Promise((resolve,reject)=>{const r=indexedDB.open(globalThis.nrVaultOwner ? 'nr-account-'+globalThis.nrVaultOwner : 'nr-local-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('vault');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function op(mode,fn){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('vault',mode),r=fn(tx.objectStore('vault'));let out;r.onsuccess=()=>{out=r.result};tx.oncomplete=()=>resolve(out);tx.onerror=()=>reject(tx.error)})}
export async function saveVault(data){const e=epoch,r=++revision;if(!crypto.subtle)throw Error('Secure browser storage unavailable');let key=await op('readonly',s=>s.get('key'));if(e!==epoch||r!==revision)return;if(!key){key=await crypto.subtle.generateKey({name:'AES-GCM',length:256},false,['encrypt','decrypt']);if(e!==epoch||r!==revision)return;await op('readwrite',s=>s.put(key,'key'))}const iv=crypto.getRandomValues(new Uint8Array(12));const body=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(JSON.stringify(data)));if(e!==epoch||r!==revision)return;await op('readwrite',s=>s.put({schema:1,iv,body},'data'))}
export async function loadVault(){const key=await op('readonly',s=>s.get('key')),data=await op('readonly',s=>s.get('data'));if(!key||!data)return null;const body=await crypto.subtle.decrypt({name:'AES-GCM',iv:data.iv},key,data.body);return JSON.parse(new TextDecoder().decode(body))}
export async function clearVault(){epoch++;revision++;await op('readwrite',s=>s.clear())}
